                var apply=new Button {Text="Apply",Left=350,Top=240,Width=85};var cancel=new Button {Text="Close",Left=450,Top=240,Width=85,DialogResult=DialogResult.Cancel};var layout=new Button {Text="Select layout frame",Left=20,Top=190,Width=160,Enabled=IsManaged(slide)};var up=new Button {Text="Move chapter up",Left=200,Top=190,Width=160};var down=new Button {Text="Move chapter down",Left=375,Top=190,Width=160};
                form.Controls.AddRange(new Control[]{new Label {Text="Chapter",Left=20,Top=24},new Label {Text="Caption",Left=20,Top=70},new Label {Text="Hierarchy level",Left=20,Top=112,Width=110},new Label {Text="Content slides move with a chapter. Close this panel to edit native fields.",Left=20,Top=150,Width=515},chapters,caption,level,all,layout,up,down,apply,cancel});form.CancelButton=cancel;form.AcceptButton=apply;
                apply.Click+=(s,e)=>{try{checkDeck();ChangeChapter(app,state.Chapters[chapters.SelectedIndex].SlideId,caption.Text,(int)level.Value);if(IsManaged(slide)){string old=slide.Tags[ShowAll];slide.Tags.Add(ShowAll,all.Checked?"1":"0");try{RefreshAll(app,false);}catch{slide.Tags.Add(ShowAll,old);throw;}}form.DialogResult=DialogResult.OK;}catch(Exception error) when(error is InvalidDataException||error is InvalidOperationException||error is System.Runtime.InteropServices.COMException){MessageBox.Show(form,error.Message,"Agenda update");}};
                layout.Click+=(s,e)=>{if(app.ActivePresentation!=managedDeck){MessageBox.Show(form,"Return to the original presentation first.","Agenda layout");return;}var fields=Fields(slide);PowerPoint.Shape frame;if(!fields.TryGetValue("frame",out frame))return;form.Close();frame.Select();};
                up.Click+=(s,e)=>{try{checkDeck();Move(app,state.Chapters[chapters.SelectedIndex].SlideId,false);form.Close();}catch(Exception error){MessageBox.Show(form,error.Message,"Agenda move");}};
                down.Click+=(s,e)=>{try{checkDeck();Move(app,state.Chapters[chapters.SelectedIndex].SlideId,true);form.Close();}catch(Exception error){MessageBox.Show(form,error.Message,"Agenda move");}};form.ShowDialog();
            }
        }
        internal static void Move(PowerPoint.Application app,int target,bool down)
        {
            var deck=app.ActivePresentation;var state=Read(app);var scopes=new Dictionary<int,int>();foreach(PowerPoint.Slide slide in deck.Slides)if(slide.Tags[Split]=="1")scopes[slide.SlideID]=slide.SlideIndex;var plan=ChapterAgendaPlanner.Move(state.Chapters,target,down,deck.Slides.Count,scopes);var ids=Enumerable.Range(plan.FirstSlide,plan.LastSlide-plan.FirstSlide+1).Select(i=>deck.Slides[i].SlideID).ToArray();app.StartNewUndoEntry();try{deck.Slides.Range(Enumerable.Range(plan.FirstSlide,plan.LastSlide-plan.FirstSlide+1).Cast<object>().ToArray()).MoveTo(plan.DestinationIndex);RefreshAll(app,false);}
            catch(Exception error){try{deck.Slides.Range(ids.Select(id=>(object)deck.Slides.FindBySlideID(id).SlideIndex).ToArray()).MoveTo(plan.FirstSlide);RefreshAll(app,false);}catch(Exception rollback){throw new InvalidOperationException("Chapter move failed and restoration was incomplete. Use Undo.",new AggregateException(error,rollback));}throw;}
        }
        internal static void Automatic(PowerPoint.Application app)
        {if(app==null||app.Presentations.Count==0||app.ActiveWindow.Selection.Type==PowerPoint.PpSelectionType.ppSelectionText)return;if(app.ActivePresentation.CustomXMLParts.SelectByNamespace(ChapterAgendaCodec.Namespace).Count>0)RefreshAll(app,false,true);}
    }
}
